def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            comps.append((color, cells))

    # The long, thin component is the color cue; recolor the nearest separate object to match it.
    cue = max(comps, key=lambda z: len(z[1]))
    cue_color, cue_cells = cue
    others = [z for z in comps if z is not cue]
    if not others:
        return grid
    def dist(comp):
        return min(abs(a-y)+abs(b-x) for a,b in cue_cells for y,x in comp[1])
    target = min(others, key=dist)
    out = [row[:] for row in grid]
    for r,c in target[1]:
        out[r][c] = cue_color
    return out
